// fakeStore is the in-package Deps fixture: a map-backed corpus the tests
// mutate between passes — no internal imports, exactly the closure shape
// cmd builds at the composition root (browse-scale D2). corpusCalls counts
// full-corpus reads, so a test can tell a drift rebuild (a fresh Corpus
// read) from an incremental reconcile (walk + sweep only). Idle closures
// floor: an idle walk returns the watermark unchanged, a nil live set
// sweeps nothing, a missing resolver resolves nothing.
type fakeStore struct {
	corpusCalls int
	entries     []Entry
	docs        map[string][]json.RawMessage
	watermark   string
	epoch       Epoch

	// Per-pass hooks (nil = idle): the walk the next pass runs, the live
	// id set it sweeps against, and an override for the per-library
	// facet doc read (nil falls through to the shared docs map).
	changed   func(after string) ([]Entry, string)
	live      func() map[string]bool
	facetDocs func(lib string) []json.RawMessage

	// changedAfters records every walk's lower bound — the watermark
	// actually handed to the closure, seeded from the build and advanced
	// by each walk's return.
	changedAfters []string
}

// deps renders the fixture as the service's closure set, recording what
// the service actually reads.
func (f *fakeStore) deps() Deps {
	return Deps{
		Epoch: func() Epoch { return f.epoch },
		Corpus: func() ([]Entry, map[string][]json.RawMessage, string) {
			f.corpusCalls++
			return f.entries, f.docs, f.watermark
		},
		Changed: func(after string) ([]Entry, string) {
			f.changedAfters = append(f.changedAfters, after)
			if f.changed == nil {
				return nil, after
			}
			return f.changed(after)
		},
		LiveIDs: func() map[string]bool {
			if f.live == nil {
				return nil
			}
			return f.live()
		},
		Resolver: aboutResolver,
		FacetDocs: func(lib string) []json.RawMessage {
			if f.facetDocs != nil {
				return f.facetDocs(lib)
			}
			return f.docs[lib]
		},
	}
}

// aboutResolver is the stub About projection: it decodes the document and
// hands back the tmdb namespace as the resolved About block — the shape
// buildFacets consumes (resolver(...)["about"]), without dragging the
// naming package into these tests.
func aboutResolver(_ string, raw json.RawMessage) map[string]any {
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil
	}
	srcs, _ := doc["sources"].(map[string]any)
	ns, _ := srcs["tmdb"].(map[string]any)
	if ns == nil {
		return nil
	}
	return map[string]any{"about": ns}
}

// genresDoc builds one series document carrying the given genre values in
// its winning namespace.
func genresDoc(genres ...string) json.RawMessage {
	g, _ := json.Marshal(genres)
	return json.RawMessage(fmt.Sprintf(`{"sources":{"tmdb":{"description":"synopsis","genres":%s}}}`, g))
}

// TestEpochRowAndCount pins the two-part scalar epoch (browse-scale D4,
// reviewer Q3): a naming-config write trips the max-updated_at leg, a
// corpus add/delete trips the row-count leg — both answer with a FULL
// rebuild (a fresh Corpus read) — while a content-row update with the
// epoch unchanged takes the incremental walk instead, never recomposing
// the corpus.
func TestEpochRowAndCount(t *testing.T) {
	f := &fakeStore{
		entries: []Entry{
			{ID: "s1", LibraryID: "1", Kind: KindSeries, DisplayName: "Ария"},
			{ID: "s2", LibraryID: "1", Kind: KindSeries, DisplayName: "Кино"},
		},
		watermark: "2026-11-06T12:00:00Z",
		epoch:     Epoch{UpdatedAt: "2026-11-06T12:00:00Z", Rows: 2},
	}
	svc := NewService(f.deps())
	svc.Build()
	if f.corpusCalls != 1 {
		t.Fatalf("build: corpus read %d times, want 1", f.corpusCalls)
	}
	if got := svc.Search("ари"); !reflect.DeepEqual(got.Series, []string{"s1"}) {
		t.Fatalf("build search: got %v, want [s1]", got.Series)
	}

	// An idle pass — epoch unchanged, walk empty, nothing swept —
	// rebuilds nothing and leaves the model answering.
	svc.Reconcile()
	if f.corpusCalls != 1 {
		t.Fatalf("idle pass rebuilt: corpus reads = %d, want 1", f.corpusCalls)
	}

	// Naming-config write: the max-updated_at leg trips ⇒ full rebuild.
	f.epoch.UpdatedAt = "2026-11-06T13:00:00Z"
	svc.Reconcile()
	if f.corpusCalls != 2 {
		t.Fatalf("config drift did not rebuild: corpus reads = %d, want 2", f.corpusCalls)
	}

	// Row delete: the count leg trips (reviewer Q3 — deletes bump no
	// updated_at) ⇒ full rebuild. The rebuild re-reads the epoch, so the
	// service now holds {13:00, 1}.
	f.epoch = Epoch{UpdatedAt: "2026-11-06T13:00:00Z", Rows: 1}
	svc.Reconcile()
	if f.corpusCalls != 3 {
		t.Fatalf("count drift did not rebuild: corpus reads = %d, want 3", f.corpusCalls)
	}

	// Content-row update (an enrichment merge) with the epoch UNCHANGED
	// — the fixture keeps exactly the stamp the rebuild last read, so the
	// drift legs are silent: the walk serves the fresh entry
	// incrementally, no corpus read is paid, and the match surface
	// follows the new name.
	f.entries = []Entry{
		{ID: "s1", LibraryID: "1", Kind: KindSeries, DisplayName: "Кипелов"},
		{ID: "s2", LibraryID: "1", Kind: KindSeries, DisplayName: "Кино"},
	}
	f.changed = func(string) ([]Entry, string) {
		return []Entry{{ID: "s1", LibraryID: "1", Kind: KindSeries, DisplayName: "Кипелов"}}, "2026-11-06T12:30:00Z"
	}
	svc.Reconcile()
	if f.corpusCalls != 3 {
		t.Fatalf("content update paid a full rebuild: corpus reads = %d, want 3", f.corpusCalls)
	}
	if got := svc.Search("кипел"); !reflect.DeepEqual(got.Series, []string{"s1"}) {
		t.Fatalf("walked entry not searchable: got %v, want [s1]", got.Series)
	}
	if got := svc.Search("Ария"); len(got.Series) != 0 {
		t.Fatalf("pre-merge composed name still matches after the walk: got %v, want none", got.Series)
	}
}

// TestReconcileSweep pins the reconcile pass's two incremental halves
// (browse-scale D4): the watermark walk runs from the CURRENT watermark
// (seeded by the build, advanced by each walk's return) and replaces the
// walked entities in place; the orphan sweep drops entries whose ids
// stopped being live — a re-identified entity's fresh id arrives on the
// walk while its old id is swept. The walk-touched library's facet
// aggregates are recomputed in the same pass.
func TestReconcileSweep(t *testing.T) {
	f := &fakeStore{
		entries: []Entry{
			{ID: "s1", LibraryID: "1", Kind: KindSeries, DisplayName: "Ария"},
			{ID: "s2", LibraryID: "1", Kind: KindSeries, DisplayName: "Кино"},
		},
		docs: map[string][]json.RawMessage{
			"1": {genresDoc("Drama"), genresDoc("Rock")},
		},
		watermark: "w1",
		epoch:     Epoch{UpdatedAt: "2026-11-06T12:00:00Z", Rows: 2},
	}
	svc := NewService(f.deps())
	svc.Build()
	if got := svc.Facets("1"); len(got) == 0 || got[0].Key != "genres" || len(got[0].Values) != 2 {
		t.Fatalf("build facets: got %+v, want two genre values", got)
	}

	// Re-identify: the row's id is minted anew — the walk delivers the
	// fresh entry, the live set no longer carries the old id, and the
	// merge changed the document's facts too. Epoch unchanged (the
	// incremental path).
	f.changed = func(string) ([]Entry, string) {
		return []Entry{{ID: "s2b", LibraryID: "1", Kind: KindSeries, DisplayName: "Кино"}}, "w2"
	}
	f.live = func() map[string]bool { return map[string]bool{"s1": true, "s2b": true} }
	f.facetDocs = func(string) []json.RawMessage { return []json.RawMessage{genresDoc("Drama"), genresDoc("Metal")} }

	svc.Reconcile()

	if got := f.changedAfters; len(got) != 1 || got[0] != "w1" {
		t.Fatalf("walk lower bound: got %v, want [w1] — the build's watermark seed", got)
	}
	if got := svc.Search("Кино"); !reflect.DeepEqual(got.Series, []string{"s2b"}) {
		t.Fatalf("re-identified entity: got %v, want [s2b]", got.Series)
	}
	if got := svc.Search("Ария"); !reflect.DeepEqual(got.Series, []string{"s1"}) {
		t.Fatalf("untouched entity swept by mistake: got %v, want [s1]", got.Series)
	}
	want := []Facet{{Key: "genres", Values: []FacetValue{{Value: "Drama", Count: 1}, {Value: "Metal", Count: 1}}}}
	if got := svc.Facets("1"); !reflect.DeepEqual(got, want) {
		t.Fatalf("touched library facets not recomputed: got %+v, want %+v", got, want)
	}

	// The next idle pass walks from the ADVANCED watermark, and a pure
	// orphan (live set drops an id with an empty walk) is swept alone —
	// the sweep is its own half of the pass, not a walk side effect.
	f.changed = nil
	svc.Reconcile()
	if got := f.changedAfters; len(got) != 2 || got[1] != "w2" {
		t.Fatalf("watermark did not advance: got %v, want second lower bound w2", got)
	}
	f.live = func() map[string]bool { return map[string]bool{"s2b": true} }
	svc.Reconcile()
	if got := svc.Search("Ария"); len(got.Series) != 0 {
		t.Fatalf("orphaned entry survived the sweep: got %v, want none", got.Series)
	}
	if got := svc.Search("Кино"); !reflect.DeepEqual(got.Series, []string{"s2b"}) {
		t.Fatalf("sweep took the live entry: got %v, want [s2b]", got.Series)
	}
}

// TestRAMBudget10k pins the read model's footprint at the design size
// (browse-scale D8): 1k series + 10k items across 8 media libraries,
// Cyrillic/Latin composed names with one unpicked alternate each, and
// 1k facet documents. The build must stay sub-second and the retained
// heap within the budget — measured as the post-GC heap delta around
// Service.Build, the fixture itself excluded (allocated before the
// baseline read).
func TestRAMBudget10k(t *testing.T) {
	const seriesCount = 1000
	const itemCount = 10000
	entries := make([]Entry, 0, seriesCount+itemCount)
	docs := map[string][]json.RawMessage{}
	for i := 0; i < seriesCount; i++ {
		lib := fmt.Sprintf("%d", i%8+1)
		entries = append(entries, Entry{
			ID:          fmt.Sprintf("ser_%s_%04d", lib, i),
			LibraryID:   lib,
			Kind:        KindSeries,
			DisplayName: fmt.Sprintf("Сериал %04d — Show %04d", i, i),
			Alternates:  []string{fmt.Sprintf("romaji title %04d", i)},
		})
		docs[lib] = append(docs[lib], genresDoc("Drama", "Rock"))
	}
	for i := 0; i < itemCount; i++ {
		lib := fmt.Sprintf("%d", i%8+1)
		entries = append(entries, Entry{
			ID:          fmt.Sprintf("itm_%s_%05d", lib, i),
			LibraryID:   lib,
			Kind:        KindItem,
			DisplayName: fmt.Sprintf("Эпизод s01e%02d — Episode %05d", i%24+1, i),
			Alternates:  []string{fmt.Sprintf("raw file name %05d.mkv", i)},
		})
	}
	f := &fakeStore{
		entries:   entries,
		docs:      docs,
		watermark: "2026-11-06T12:00:00Z",
		epoch:     Epoch{UpdatedAt: "2026-11-06T12:00:00Z", Rows: seriesCount + itemCount},
	}

	runtime.GC()
	var before runtime.MemStats
	runtime.ReadMemStats(&before)

	svc := NewService(f.deps())
	start := time.Now()
	svc.Build()
	elapsed := time.Since(start)

	runtime.GC()
	var after runtime.MemStats
	runtime.ReadMemStats(&after)
	runtime.KeepAlive(svc)

	ram := int64(after.HeapAlloc) - int64(before.HeapAlloc)
	const ramBudget = 5 << 20 // 5 MB — the ~3.3 MB design budget with ~50% headroom
	t.Logf("built %d entries + %d facet docs in %s; retained heap delta %d bytes (%.2f MB, budget %.2f MB)",
		seriesCount+itemCount, len(docs["1"])*8, elapsed, ram, float64(ram)/(1<<20), float64(ramBudget)/(1<<20))
	if elapsed > time.Second {
		t.Errorf("build took %s — the D8 budget is sub-second", elapsed)
	}
	if ram > ramBudget {
		t.Errorf("read model retained %d bytes — over the %d-byte budget", ram, ramBudget)
	}

	// The built model actually serves: a query hits through both the
	// Cyrillic and Latin legs, and the facet aggregates resolved.
	if got := svc.Search("сериал 0042"); len(got.Series) == 0 {
		t.Fatalf("fixture series unsearchable: got %v", got.Series)
	}
	if got := svc.Search("show 0042"); len(got.Series) == 0 {
		t.Fatalf("fixture series unsearchable on the Latin leg: got %v", got.Series)
	}
	if got := svc.Facets("1"); len(got) == 0 || got[0].Key != "genres" {
		t.Fatalf("facet aggregates absent at design size: got %+v", got)
	}
}

// TestReconcileWakePoke pins the wake channel's coalescing contract (the
// janitor wake idiom): a burst of pokes delivers exactly one pending
// pass, a poke on a full buffer never blocks, and the channel is never
// closed.
func TestReconcileWakePoke(t *testing.T) {
	svc := NewService(Deps{})
	ch := svc.WakeChan()
	svc.Wake()
	svc.Wake() // burst — must coalesce into one pending pass
	select {
	case <-ch:
	default:
		t.Fatal("wake poke not deliverable")
	}
	select {
	case <-ch:
		t.Fatal("second poke delivered — a burst must coalesce into one pass")
	default:
	}
	svc.Wake() // refill, then one more on the full buffer — must not block
	done := make(chan struct{})
	go func() {
		svc.Wake()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("Wake blocked on a full buffer")
	}
}
